"""Extra exhaustive verification of reduce.py."""
import itertools
from problems import ThreeSat, IndependentSet
from reduce import reduce
from test_reduce import solve_three_sat, solve_independent_set

def clauses_over(vs):
    out = []
    for signs in itertools.product([1, -1], repeat=len(vs)):
        out.append([signs[i] * vs[i] for i in range(len(vs))])
    return out

def check(inst, bad):
    src = solve_three_sat(inst)
    tgt_inst = reduce(inst)
    IndependentSet.validate(tgt_inst)
    tgt = solve_independent_set(tgt_inst)
    if src != tgt:
        bad.append((inst, tgt_inst, src, tgt))

bad = []
count = 0

# Exhaustive: m=3, all clause multisets of size 0..3 from the 8 clauses
base3 = clauses_over([1, 2, 3])
for r in range(0, 4):
    for combo in itertools.combinations_with_replacement(range(8), r):
        inst = {"num_vars": 3, "clauses": [list(base3[i]) for i in combo]}
        check(inst, bad); count += 1

# Exhaustive: m=4, clauses over any 3 of 4 vars, all multisets of size 0..2
base4 = []
for vs in itertools.combinations([1, 2, 3, 4], 3):
    base4.extend(clauses_over(list(vs)))
for r in range(0, 3):
    for combo in itertools.combinations_with_replacement(range(len(base4)), r):
        inst = {"num_vars": 4, "clauses": [list(base4[i]) for i in combo]}
        check(inst, bad); count += 1

# Exhaustive: m=5, all single clauses over any 3 of 5 vars
base5 = []
for vs in itertools.combinations([1, 2, 3, 4, 5], 3):
    base5.extend(clauses_over(list(vs)))
for c in base5:
    check({"num_vars": 5, "clauses": [list(c)]}, bad); count += 1

# Empty clauses with m=0..6
for m in range(0, 7):
    check({"num_vars": m, "clauses": []}, bad); count += 1

print("exhaustive count:", count, "failures:", len(bad))
for b in bad[:5]:
    print(b)
EOF
